from pathlib import Path
import hashlib
import json

ROOT = Path(__file__).resolve().parents[3]

def read(path):
    return json.loads((ROOT/path).read_text(encoding='utf-8'))

def sha(path):
    return hashlib.sha256((ROOT/path).read_bytes()).hexdigest()

def source(key,path,url,role,locator=None):
    status='SAVED_DERIVED_FROM_OFFICIAL_SOURCE' if key in {'original_arrete_manifest','original_arrete_codes'} else 'SAVED_OFFICIAL_SOURCE'
    return dict(key=key,path=path,official_url=url,role=role,locator=locator,sha256=sha(path),bytes=(ROOT/path).stat().st_size,status=status,format_note='Web text snapshot, not original HTML/PDF bytes.' if path.endswith('_web.txt') or 'lf2024_art73_' in path else None)

